from fractions import Fraction


def evaluate(expression):
    if not isinstance(expression, str):
        raise ValueError("Expression must be a string")

    stripped = expression.strip()
    if stripped == '':
        raise ValueError("Empty expression")

    pos = 0
    length = len(expression)
    WS = ' \t\r\n'

    def skip_ws():
        nonlocal pos
        while pos < length and expression[pos] in WS:
            pos += 1

    def parse_expression():
        """expr = term (('+' | '-') term)*"""
        nonlocal pos
        left = parse_term()
        while True:
            skip_ws()
            if pos < length and expression[pos] == '+':
                pos += 1
                left = left + parse_term()
            elif pos < length and expression[pos] == '-':
                pos += 1
                left = left - parse_term()
            else:
                break
        return left

    def parse_term():
        """term = factor (('*' | '/') factor)*"""
        nonlocal pos
        left = parse_factor()
        while True:
            skip_ws()
            if pos < length and expression[pos] == '*':
                pos += 1
                left = left * parse_factor()
            elif pos < length and expression[pos] == '/':
                pos += 1
                right = parse_factor()
                left = left / right  # Fraction raises ZeroDivisionError if right == 0
            else:
                break
        return left

    def parse_factor():
        """factor = ('+' | '-')* primary"""
        nonlocal pos
        skip_ws()
        sign = 1
        while pos < length and expression[pos] in '+-':
            if expression[pos] == '-':
                sign = -sign
            pos += 1
            skip_ws()
        return parse_primary() * sign

    def parse_primary():
        """primary = INT | '(' expr ')'"""
        nonlocal pos
        skip_ws()
        if pos >= length:
            raise ValueError("Missing operand")

        ch = expression[pos]

        if ch == '(':
            pos += 1
            value = parse_expression()
            skip_ws()
            if pos >= length:
                raise ValueError("Unmatched parenthesis: missing ')'")
            if expression[pos] != ')':
                raise ValueError(
                    f"Expected ')' but got {expression[pos]!r} at position {pos}"
                )
            pos += 1
            return value

        if ch.isdigit():
            start = pos
            while pos < length and expression[pos].isdigit():
                pos += 1
            return Fraction(int(expression[start:pos]))

        raise ValueError(f"Unexpected character {ch!r} at position {pos}")

    result = parse_expression()
    skip_ws()
    if pos < length:
        raise ValueError(
            f"Unexpected character {expression[pos]!r} at position {pos}"
        )
    return result
